<?php
declare(strict_types=1);require_once '../config/config.php';require_once '../includes/church-book-functions.php';requireLogin();cb_require_permission('wedding_vows.manage');if(!isset($conn)||!($conn instanceof mysqli))die('Database connection not found.');$conn->set_charset('utf8mb4');if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: ./');exit;}cb_verify_csrf();$action=cb_clean($_POST['action']??'');
if($action==='save_signature_lines'){cb_save_wedding_signature_lines($conn,(array)($_POST['signature_lines']??[]));cb_flash('Wedding record signature lines saved.');header('Location: ./');exit;}
if($action==='delete'){$id=cb_int($_POST['id']??0);if($id<=0){cb_flash('Invalid wedding record.','error');header('Location: ./');exit;}$stmt=$conn->prepare("DELETE FROM wedding_vows WHERE id=?");$stmt->bind_param('i',$id);$stmt->execute();$ok=$stmt->affected_rows>0;$stmt->close();cb_flash($ok?'Wedding record deleted.':'Wedding record was not found.',$ok?'success':'error');header('Location: ./');exit;}if($action!=='save'){cb_flash('Invalid action.','error');header('Location: ./');exit;}
$id=cb_int($_POST['id']??0);$f=[];foreach(['register_no','wedding_date','wedding_time','venue','status','groom_name','groom_phone','groom_address','groom_father','groom_mother','bride_name','bride_phone','bride_address','bride_father','bride_mother','ceremony_type','banns_date_1','banns_date_2','banns_date_3','marriage_licence_no','certificate_no','witness_1','witness_2','officiant','assisting_minister','vows_text','scripture_theme','remarks'] as $k)$f[$k]=cb_clean($_POST[$k]??'');$f['groom_member_id']=cb_nullable_int($_POST['groom_member_id']??'');$f['bride_member_id']=cb_nullable_int($_POST['bride_member_id']??'');
if($f['wedding_date']===''||!cb_valid_date($f['wedding_date'])||$f['groom_name']===''||$f['bride_name']===''){cb_flash('Wedding date, groom name and bride name are required.','error');header('Location: ./');exit;}
if(!in_array($f['status'],['Scheduled','Banns','Solemnized','Postponed','Cancelled'],true))$f['status']='Scheduled';if(!in_array($f['ceremony_type'],['Banns','Licence','Special Licence','Other'],true))$f['ceremony_type']='Banns';foreach(['banns_date_1','banns_date_2','banns_date_3'] as $k)if($f[$k]!==''&&!cb_valid_date($f[$k]))$f[$k]='';
foreach(['register_no','wedding_time','venue','groom_phone','groom_address','groom_father','groom_mother','bride_phone','bride_address','bride_father','bride_mother','banns_date_1','banns_date_2','banns_date_3','marriage_licence_no','certificate_no','witness_1','witness_2','officiant','assisting_minister','vows_text','scripture_theme','remarks'] as $k)if($f[$k]==='')$f[$k]=null;
try{
$vals=[$f['register_no'],$f['wedding_date'],$f['wedding_time'],$f['venue'],$f['status'],$f['groom_member_id'],$f['groom_name'],$f['groom_phone'],$f['groom_address'],$f['groom_father'],$f['groom_mother'],$f['bride_member_id'],$f['bride_name'],$f['bride_phone'],$f['bride_address'],$f['bride_father'],$f['bride_mother'],$f['ceremony_type'],$f['banns_date_1'],$f['banns_date_2'],$f['banns_date_3'],$f['marriage_licence_no'],$f['certificate_no'],$f['witness_1'],$f['witness_2'],$f['officiant'],$f['assisting_minister'],$f['vows_text'],$f['scripture_theme'],$f['remarks']];
$types='sssssisssssissssssssssssssssss';
if($id>0){$sql="UPDATE wedding_vows SET register_no=?,wedding_date=?,wedding_time=?,venue=?,status=?,groom_member_id=?,groom_name=?,groom_phone=?,groom_address=?,groom_father=?,groom_mother=?,bride_member_id=?,bride_name=?,bride_phone=?,bride_address=?,bride_father=?,bride_mother=?,ceremony_type=?,banns_date_1=?,banns_date_2=?,banns_date_3=?,marriage_licence_no=?,certificate_no=?,witness_1=?,witness_2=?,officiant=?,assisting_minister=?,vows_text=?,scripture_theme=?,remarks=? WHERE id=?";$vals[]=$id;$types.='i';}
else{$sql="INSERT INTO wedding_vows(register_no,wedding_date,wedding_time,venue,status,groom_member_id,groom_name,groom_phone,groom_address,groom_father,groom_mother,bride_member_id,bride_name,bride_phone,bride_address,bride_father,bride_mother,ceremony_type,banns_date_1,banns_date_2,banns_date_3,marriage_licence_no,certificate_no,witness_1,witness_2,officiant,assisting_minister,vows_text,scripture_theme,remarks,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";$vals[]=cb_current_user_id();$types.='i';}
$stmt=$conn->prepare($sql);cb_bind($stmt,$types,$vals);$stmt->execute();$stmt->close();cb_flash($id>0?'Wedding record updated successfully.':'Wedding record added successfully.');
}catch(Throwable $e){cb_flash(str_contains(strtolower($e->getMessage()),'duplicate')?'Register number already exists.':'Could not save wedding record: '.$e->getMessage(),'error');}
header('Location: ./');exit;
